"""Generate Android and browser descriptions from the shared verified catalog."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
codes=json.loads((ROOT/'printing/printer_errors.json').read_text())['codes']
messages={k:v['title']+'（'+k+'）。'+v['action'] for k,v in codes.items()}
java='''package local.liuying.studio;
// Generated by tools/generate_printer_errors.py; edit printing/printer_errors.json.
final class PrinterAlerts {
 static final java.util.Map<String,String> MESSAGES=new java.util.LinkedHashMap<>();
 static {
'''
for k,v in messages.items():java+='  MESSAGES.put('+json.dumps(k)+','+json.dumps(v,ensure_ascii=False)+');\n'
java+=''' }
 static String code(String value){
  String c=value==null?"":value.trim();if(c.isEmpty()||c.equals("0"))return "";
  String known=MESSAGES.get(c);if(known!=null)return known;
  c=c.replaceAll("[^0-9A-Za-z_-]","_");if(c.length()>80)c=c.substring(0,80);
  return "未识别的打印机错误（"+c+"）。请检查设备提示并保留错误码；不要重复提交未确认的任务。";
 }
 static String describe(String value){
  if(value==null)return "";java.util.List<String> messages=new java.util.ArrayList<>();
  for(String token:value.split("[:%,;\\\\s]+")){String m=code(token);if(!m.isEmpty()&&!messages.contains(m))messages.add(m);}
  return String.join("；",messages);
 }
}
'''
(ROOT/'src/PrinterAlerts.java').write_text(java)
js='''// Generated by tools/generate_printer_errors.py; edit printing/printer_errors.json.
(function(){'use strict';
const catalog='''+json.dumps(codes,ensure_ascii=False,separators=(',',':'))+''';
function tokens(value){return [...new Set(String(value??'').split(/[:%,;\\s]+/).filter(c=>c&&c!=='0'))];}
function safe(value){return String(value).replace(/[^0-9A-Za-z_-]/g,'_').slice(0,80);}
function code(value){const c=String(value??'').trim();if(!c||c==='0')return '';const row=Object.hasOwn(catalog,c)?catalog[c]:null;return row?`${row.title}（${c}）。${row.action}`:`未识别的打印机错误（${safe(c)}）。请检查设备提示并保留错误码；不要重复提交未确认的任务。`;}
function describe(value){return tokens(value).map(code).join('；');}
function summary(value){return tokens(value).map(c=>Object.hasOwn(catalog,c)?catalog[c].title:`未识别错误（${safe(c)}）`).join('；');}
function rewrite(value){return String(value??'').replace(/打印机告警[（(]([0-9A-Za-z_-]+)[）)]/g,(_,c)=>code(c)).replace(/打印机拒绝任务[：:]\\s*(\\d+)\\b/g,(_,c)=>'打印机拒绝任务：'+code(c));}
window.PrinterErrors=Object.freeze({describe,code,summary,rewrite});
})();
'''
(ROOT/'assets/printer-errors.js').write_text(js)
print('Generated',len(codes),'entries for Java and JavaScript')
